export const coastTopic={id:'geography.a.coasts',title:'Coastal landscapes and processes',discipline:'Physical geography'};
const q=(unit,n,prompt,options,answer,why,concept)=>({id:`geo.a.coast.${unit}.${n}`,prompt,options,answer,why,concept:'geo.a.coast.'+concept});
